package br.com.onda;
import android.app.*;import android.content.*;import android.net.Uri;import android.widget.*;
import androidx.media3.common.*;import androidx.media3.session.MediaController;import androidx.media3.session.SessionToken;
import com.google.common.util.concurrent.ListenableFuture;
import java.io.*;import java.util.*;import java.util.concurrent.TimeUnit;
import org.junit.Test;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
@androidx.media3.common.util.UnstableApi
public class AudioChapterTest {
 private final Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();
 private AudioChapterScanner.Control control(){return new AudioChapterScanner.Control(){public void check()throws IOException{if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();}public void progress(long position,long duration){assertTrue(position>=0);}};}
 private interface Check{boolean ready()throws Exception;}
 private void waitFor(Check check)throws Exception{for(int i=0;i<300;i++){boolean[] ready={false};ins.runOnMainSync(()->{try{ready[0]=check.ready();}catch(Exception e){throw new RuntimeException(e);}});if(ready[0])return;Thread.sleep(50);}fail("Audio chapter scenario timed out");}
 private Object field(Object target,String name)throws Exception{java.lang.reflect.Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}
 @Test public void actualPcmPausesAreDetectedAndOriginalIsUnchanged()throws Exception{File source=AudioTestFixtures.collection(c);byte[] original=java.nio.file.Files.readAllBytes(source.toPath());try{AudioChapterScanner.Result result=AudioChapterScanner.scan(c,Uri.fromFile(source),control());assertEquals(3,result.starts.size());assertEquals(32650,result.starts.get(1),300);assertEquals(65450,result.starts.get(2),300);assertEquals(96600,result.duration,300);assertArrayEquals(original,java.nio.file.Files.readAllBytes(source.toPath()));}finally{source.delete();}}
 @Test public void decodedAacAndCancelledScanKeepSavedMarkers()throws Exception{File aac=File.createTempFile("chapter-aac-",".mp4",c.getCacheDir()),wave=AudioTestFixtures.collection(c);try{try(InputStream in=ins.getContext().getAssets().open("combined.mp4");OutputStream out=new FileOutputStream(aac)){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}assertEquals(1,AudioChapterScanner.scan(c,Uri.fromFile(aac),control()).starts.size());Uri uri=Uri.fromFile(wave);String stamp=AudioChapterStore.stamp(c,uri);AudioChapterStore.Data saved=new AudioChapterStore.Data(96600,Arrays.asList(new AudioChapterStore.Chapter(0,"Inteiro")));AudioChapterStore.save(c,uri,stamp,saved);int[] checks={0};try{AudioChapterScanner.scan(c,uri,new AudioChapterScanner.Control(){public void check()throws IOException{if(++checks[0]>=3)throw new InterruptedIOException("Cancelado");}public void progress(long p,long d){}});fail("Scan should cancel");}catch(InterruptedIOException expected){}AudioChapterStore.Data restored=AudioChapterStore.load(c,uri,stamp,96600);assertNotNull(restored);assertEquals("Inteiro",restored.chapters.get(0).title);assertEquals(1,restored.chapters.size());assertNull(AudioChapterStore.load(c,uri,"changed",96600));}finally{aac.delete();wave.delete();}}
 @Test public void activityScansAndChoosesPositionInSameAudioQueue()throws Exception{File source=AudioTestFixtures.collection(c);ListenableFuture<MediaController>[] future=new ListenableFuture[1];AudioChaptersActivity[] screen={null};MediaController[] player={null};try{ins.runOnMainSync(()->future[0]=new MediaController.Builder(c,new SessionToken(c,new ComponentName(c,PlaybackService.class))).buildAsync());player[0]=future[0].get(10,TimeUnit.SECONDS);Uri uri=Uri.fromFile(source);ins.runOnMainSync(()->{player[0].pause();player[0].setMediaItem(new MediaItem.Builder().setMediaId("chapter-native").setUri(uri).setMediaMetadata(new MediaMetadata.Builder().setTitle("Coletânea de teste").build()).build());player[0].prepare();});waitFor(()->player[0].getPlaybackState()==Player.STATE_READY);screen[0]=(AudioChaptersActivity)ins.startActivitySync(new Intent(c,AudioChaptersActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->((Button)field(screen[0],"analyze")).isEnabled());ins.runOnMainSync(()->{try{((Button)field(screen[0],"analyze")).performClick();}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->!(Boolean)field(screen[0],"busy")&&field(screen[0],"data")!=null);ins.runOnMainSync(()->{try{ListView list=(ListView)field(screen[0],"list");assertEquals(3,list.getAdapter().getCount());list.performItemClick(list.getAdapter().getView(1,null,list),1,1);}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->player[0].getPlayWhenReady()&&player[0].getCurrentPosition()>32000);ins.runOnMainSync(()->{assertEquals("chapter-native",player[0].getCurrentMediaItem().mediaId);assertEquals(1,player[0].getMediaItemCount());assertEquals(uri,player[0].getCurrentMediaItem().localConfiguration.uri);assertTrue(player[0].getCurrentPosition()<35000);});}finally{ins.runOnMainSync(()->{if(screen[0]!=null)screen[0].finish();if(player[0]!=null){player[0].pause();player[0].stop();player[0].clearMediaItems();}if(future[0]!=null)MediaController.releaseFuture(future[0]);});ins.waitForIdleSync();source.delete();}}
}
